import{_ as a,o as s,c as i,a3 as n}from"./chunks/framework.I6s8z2kk.js";const m=JSON.parse('{"title":"Packages and memberships","description":"","frontmatter":{},"headers":[],"relativePath":"user/client/packages-memberships.md","filePath":"user/client/packages-memberships.md"}'),t={name:"user/client/packages-memberships.md"};function r(o,e,c,l,h,d){return s(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="packages-and-memberships" tabindex="-1">Packages and memberships <a class="header-anchor" href="#packages-and-memberships" aria-label="Permalink to &quot;Packages and memberships&quot;">​</a></h1><h2 id="packages" tabindex="-1">Packages <a class="header-anchor" href="#packages" aria-label="Permalink to &quot;Packages&quot;">​</a></h2><p>A <strong>package</strong> is a bundle of sessions for one service, bought once at a lower price per session.</p><ul><li>Buy it from the service. It is <strong>pending</strong> until payment succeeds, then <strong>active</strong>.</li><li>Packages are always paid online, never on arrival.</li><li>A center can pause a package. A paused package is not shown and cannot be bought, but packages you already own keep working.</li><li>Book a session from your package. It is <strong>confirmed immediately</strong> and costs nothing more. Each booking uses one session.</li><li>When the sessions run out the package is <strong>exhausted</strong>. It also <strong>expires</strong> after its validity period, counted from when it became active.</li><li>A package linked to a trainer can only be used with that trainer.</li><li>You can give a package a <strong>knight name</strong> of your own and change it any time. The center can mark a package as <strong>controlled</strong>; you cannot change that.</li><li>Cancelling a session booked with a package gives the session back.</li><li>The center can <strong>cancel</strong> a package, or refund its purchase. The package becomes <strong>cancelled</strong>, its upcoming sessions are cancelled too, and you are notified.</li></ul><h2 id="memberships" tabindex="-1">Memberships <a class="header-anchor" href="#memberships" aria-label="Permalink to &quot;Memberships&quot;">​</a></h2><p>A <strong>membership</strong> gives you free visits to a center for a period.</p><ul><li>Buy it online. It becomes <strong>active</strong> after payment and lasts for its duration, counted from activation.</li><li>Check in for a <strong>visit</strong> while it is active. Visits are free and confirmed immediately.</li><li>Each membership has a <strong>limit of visits per day</strong>.</li><li>You are reminded before a package or membership expires.</li></ul><h2 id="where-to-see-them" tabindex="-1">Where to see them <a class="header-anchor" href="#where-to-see-them" aria-label="Permalink to &quot;Where to see them&quot;">​</a></h2><p><strong>My packages</strong> and <strong>My memberships</strong> list yours with their status (pending, active, exhausted, expired, cancelled).</p><h3 id="inviting-a-friend" tabindex="-1">Inviting a friend <a class="header-anchor" href="#inviting-a-friend" aria-label="Permalink to &quot;Inviting a friend&quot;">​</a></h3><p>If your membership includes free visits, you can invite another client on one of the day&#39;s free visits. The visit is booked in your friend&#39;s name, is free and confirmed at once, and counts against your daily limit. Every invite is recorded on your membership.</p>',11)])])}const p=a(t,[["render",r]]);export{m as __pageData,p as default};
